-- Step AX-2: the two French casement drawing templates.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
-- RUN sql/step-ax1-french-containment.sql FIRST.
--
-- Nathan (13 Oct 2026): French casements are sold plain, with a fanlight
-- over, and stormproof. These are Integrate's own templates from
-- DrawingBoard Config, CW group "3. Combination Flush Casements"
-- (docs/integrate-L31115-french-casements.txt):
--
--    10  French Casement                1199 x 1313
--    11  French Casement With Fanlight   899 x 1499, transom at 304
--
-- Integrate's names are kept exactly: both already describe the window.
--
-- Each tree was GENERATED by the board's own code — buildCasementFrame at
-- Integrate's size, the transom picker for 11, then "Change to: French
-- casement" — so each template is exactly what the board would build, and
-- the geometry is Integrate's:
--
--    10  interior 1125 x 1219   one pair, each leaf 556.5 x 1211   A1 / B1
--    11  interior  825 x 1405   fanlight 825 x 304 -> 817 x 296    A1
--        = 304 + 27 + 1074      pair 825 x 1074 -> 406.5 x 1066    A2 / B2
--
-- Each leaf is 57 thick, not a casement's 54, and has TWO DIFFERENT stiles:
-- an outer 62 and a meeting stile of 63 on its inner edge, where
-- 63 = (midRail 130 - gap 4) / 2. The RIGHT leaf is the master, which is
-- Integrate's default, and the board offers the other on the pair's panel.
--
-- The fanlight's bottom rail is 62 (Nathan's default of 12 Oct, which the
-- live profile now holds as casementSashPart.defaultFanlightBottomHeight);
-- the French leaves keep the ordinary 83.
--
-- NO stored ironmongery list: the default rules price it and follow the
-- openings (difference 4 in docs/integrate-differences.md).
--
-- NO stored surround list either, which is new in this step. Integrate's own
-- templates carry a "Nosing in Solid Redwood", but Integrate recalculates
-- the surround the first time a drawing is saved and the nosing disappears —
-- every SAVED Integrate drawing the reviewer has read has architrave only.
-- Nathan (13 Oct): GlazePro leaves it off, so a new drawing prices the
-- surround through the allocator like every other GlazePro drawing.
-- sql/step-ax3 takes it off the four Step AV templates for the same reason.
--
-- Product and Quantity are both is_required (Step AQ), so the product code is
-- looked up BY LABEL — the product reference list came from Integrate and its
-- codes are not in the repository — and the script fails loudly rather than
-- writing a code that would look set and still fail the check.

BEGIN;

DO $$
DECLARE
  _profile_id    bigint;
  _casement_code text;
  _templates     jsonb := '[{"name":"French Casement","sort_order":80,"tree":{"key":"item_l9nnzyz","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile","quantity":1,"product":"casement"},"children":[{"key":"paint_0dhn3j9","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_6qtfh8k","part_type":"notesPart","values":{},"children":[]},{"key":"price_oxez3m2","part_type":"pricePart","values":{},"children":[]},{"key":"frame_l2nz67p","part_type":"assemblyFramePart","values":{"width":1199,"height":1313,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"french_conaq8e","part_type":"frenchCasementPart","values":{"casementTypeId":"open_out","thickness":57,"midRail":130,"gapBetweenMeetingStiles":4,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"masterLeaf":"right"},"children":[{"key":"french_conaq8e_left","part_type":"leftFrenchCasementSashPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":57,"topHeight":62,"leftWidth":62,"rightWidth":63,"bottomHeight":83,"isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"french_conaq8e_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"french_conaq8e_right","part_type":"rightFrenchCasementSashPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":57,"topHeight":62,"leftWidth":63,"rightWidth":62,"bottomHeight":83,"isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"french_conaq8e_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]}]},{"key":"cill_drmc1g7","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}},{"name":"French Casement With Fanlight","sort_order":90,"tree":{"key":"item_dhjv0tu","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"softwood","sashMaterialId":"softwood","cillMaterialId":"utile","quantity":1,"product":"casement"},"children":[{"key":"paint_1nei8px","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isCasementMpls":true},"children":[]},{"key":"notes_j3rjw39","part_type":"notesPart","values":{},"children":[]},{"key":"price_119te35","part_type":"pricePart","values":{},"children":[]},{"key":"frame_np9i2kk","part_type":"assemblyFramePart","values":{"width":899,"height":1499,"leftWidth":37,"rightWidth":37,"topHeight":47,"bottomHeight":47,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":20,"cillAngle":6,"rakeFrame":false,"archHead":false},"children":[{"key":"trans_ikcl0ed","part_type":"transomPart","values":{"offset":304,"thicknessInFrame":27,"transomStopSize":20,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_cthik4y","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"btmRailShapeId":"square","toBeReplaced":true},"children":[{"key":"cas_cthik4y_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"french_vfvangd","part_type":"frenchCasementPart","values":{"casementTypeId":"open_out","thickness":57,"midRail":130,"gapBetweenMeetingStiles":4,"mechanicalClearanceLeft":4,"mechanicalClearanceRight":4,"mechanicalClearanceTop":4,"mechanicalClearanceBottom":4,"masterLeaf":"right"},"children":[{"key":"french_vfvangd_left","part_type":"leftFrenchCasementSashPart","values":{"operation":"left_hand_hung","casementTypeId":"open_out","thickness":57,"topHeight":62,"leftWidth":62,"rightWidth":63,"bottomHeight":83,"isMasterLeaf":false,"toBeReplaced":true},"children":[{"key":"french_vfvangd_left_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]},{"key":"french_vfvangd_right","part_type":"rightFrenchCasementSashPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":57,"topHeight":62,"leftWidth":63,"rightWidth":62,"bottomHeight":83,"isMasterLeaf":true,"toBeReplaced":true},"children":[{"key":"french_vfvangd_right_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":16,"glazingTolerance":2},"children":[]}]}]},{"key":"cill_jt42h6e","part_type":"cillPart","values":{"height":47,"depth":128},"children":[]}]}]}}]'::jsonb;
  _row           record;
  _tree          jsonb;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'casement' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''casement'' — the casement profile must exist first';
  END IF;

  SELECT code INTO _casement_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'casement' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _casement_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''Casement'' — run: SELECT code, label FROM reference_options WHERE category = ''product'' ORDER BY sort_order;';
  END IF;

  -- A French template that cannot be saved is worse than no template, so
  -- stop if sql/step-ax1 has not run.
  IF NOT EXISTS (
    SELECT 1 FROM part_type_children
    WHERE parent_code = 'frenchCasementPart' AND child_code = 'leftFrenchCasementSashPart'
  ) THEN
    RAISE EXCEPTION 'Containment for the French parts is missing — run sql/step-ax1-french-containment.sql first';
  END IF;

  IF jsonb_array_length(_templates) <> 2 THEN
    RAISE EXCEPTION 'Expected 2 templates in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_casement_code), true);

    IF EXISTS (SELECT 1 FROM public.drawing_templates WHERE name = _row.name) THEN
      UPDATE public.drawing_templates
      SET tree = _tree, default_profile_id = _profile_id,
          sort_order = _row.sort_order, updated_at = now()
      WHERE name = _row.name;
      RAISE NOTICE 'Step AX-2: % updated in place', _row.name;
    ELSE
      INSERT INTO public.drawing_templates
        (name, family, group_name, window_type, default_profile_id, tree, sort_order, is_active)
      VALUES (_row.name, 'casement', 'Combination Flush Casements', 'Casement',
              _profile_id, _tree, _row.sort_order, TRUE);
      RAISE NOTICE 'Step AX-2: % created', _row.name;
    END IF;
  END LOOP;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. The casement templates, the two new ones last in their group, each with
--    Product and Quantity set.
SELECT name, group_name, sort_order, is_active,
       tree #>> '{values,product}'  AS product_code,
       tree #>> '{values,quantity}' AS quantity
FROM   public.drawing_templates
WHERE  family = 'casement'
ORDER  BY sort_order;

-- 2. Each French template's shape: one pair with two leaves, the leaves'
--    thickness (57), their stiles (62 / 63 and 63 / 62), which is the
--    master, and NO mullion. Expect mullions 0 for both and transoms 1 for
--    "French Casement With Fanlight".
SELECT t.name,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "frenchCasementPart")'))           AS pairs,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "leftFrenchCasementSashPart")'))   AS left_leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "rightFrenchCasementSashPart")'))  AS right_leaves,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "mullionPart")'))                  AS mullions,
       (SELECT count(*) FROM jsonb_path_query(t.tree, '$.**.part_type ? (@ == "transomPart")'))                  AS transoms,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.isMasterLeaf') v)                         AS master_flags,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.thickness') v)                            AS thicknesses,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(t.tree, '$.**.values.bottomHeight') v)                         AS bottom_rails
FROM   public.drawing_templates t
WHERE  t.name IN (
--     'French Casement',
--     'French Casement With Fanlight'
)
ORDER  BY t.sort_order;

-- 3. Neither French template carries a stored surround or ironmongery list.
--    Expect NULL in both columns for both rows.
SELECT t.name,
       t.tree #> '{values,surroundLines}' AS surrounds,
       t.tree #> '{children}' -> 0 #> '{values,ironmongeryLines}' AS ironmongery_first_child
FROM   public.drawing_templates t
WHERE  t.name IN (
--     'French Casement',
--     'French Casement With Fanlight'
)
ORDER  BY t.sort_order;


-- ---------------------------------------------------------------------------
-- DO NOT RUN — rollback, only if this step has to be undone
-- ---------------------------------------------------------------------------
